var MATRIX = loadCivMatrix();
function civKeyNorm(civKey) {
  return civKey.trim().toLowerCase();
}
function civTypCywilizacjiKey(civKey) {
  const key = civKeyNorm(civKey);
  const civ = civs_default.cywilizacje.find(
    (c) => String(c.ikonaId ?? "").toLowerCase() === key || String(c.typCywilizacji ?? "").toLowerCase() === key || String(c.Cywilizacja ?? "").toLowerCase() === key
  );
  const typ = civ?.typCywilizacji;
  if (typeof typ === "string" && typ.trim()) return typ.trim().toLowerCase();
  return key;
}
function sameCultureCircle(playerCivKey, otherCivKey) {
  if (!playerCivKey?.trim() || !otherCivKey?.trim()) return false;
  return civTypCywilizacjiKey(playerCivKey) === civTypCywilizacjiKey(otherCivKey);
}

// src/game/society-inputs.ts
function clearCityCultureMix(city) {
  delete city.ownCultureShare;
  delete city.kulturaOwnShare;
}

// src/game/conquest-stability.ts
function onCityCapturedCulture(city, newOwnerId, previousOwnerId, opts) {
  if (newOwnerId === void 0 || previousOwnerId === void 0 || newOwnerId === previousOwnerId) {
    return;
  }
  const civKey = opts?.civKeyForOwner;
  if (civKey && sameCultureCircle(civKey(newOwnerId), civKey(previousOwnerId))) {
    clearCityCultureMix(city);
    return;
  }
  const prev = Math.max(0, Math.min(1, city.ownCultureShare ?? city.kulturaOwnShare ?? 1));
  city.ownCultureShare = Math.max(0, Math.min(1, 1 - prev));
  city.kulturaOwnShare = city.ownCultureShare;
}

